import React, { useEffect, useState } from "react";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

const API = "http://localhost:8000";

const S = {
  page: {
    background: "#f4f7fb",
    minHeight: "100vh",
    padding: 20,
    fontFamily: "sans-serif",
  },

  header: {
    background: "white",
    padding: 20,
    borderRadius: 12,
    marginBottom: 20,
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))",
    gap: 16,
    marginBottom: 20,
  },

  card: {
    background: "white",
    borderRadius: 12,
    padding: 18,
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  },

  label: {
    color: "#666",
    fontSize: 14,
    marginBottom: 8,
  },

  value: {
    fontSize: 30,
    fontWeight: 700,
  },

  alert: {
    background: "#fff0f0",
    border: "1px solid #ffb3b3",
    color: "#b00020",
    padding: 12,
    borderRadius: 10,
    marginBottom: 10,
    fontWeight: 600,
  },

  select: {
    padding: 12,
    borderRadius: 10,
    border: "1px solid #ddd",
    fontSize: 16,
    marginBottom: 20,
  },
};

export default function App() {
  const [patients, setPatients] = useState([]);
  const [selected, setSelected] = useState("P0001");
  const [dashboard, setDashboard] = useState(null);

  useEffect(() => {
    fetch(`${API}/patients`)
      .then((r) => r.json())
      .then(setPatients);
  }, []);

  useEffect(() => {
    fetch(`${API}/patient/${selected}`)
      .then((r) => r.json())
      .then(setDashboard);
  }, [selected]);

  if (!dashboard) {
    return <div style={{ padding: 20 }}>Loading dashboard...</div>;
  }

  const p = dashboard.patient;
  const s = dashboard.summary;

  return (
    <div style={S.page}>

      <div style={S.header}>
        <h1>🏥 IoT Patient Dashboard</h1>
        <p>Real-time monitoring for wearable IoT sensors</p>
      </div>

      <select
        style={S.select}
        value={selected}
        onChange={(e) => setSelected(e.target.value)}
      >
        {patients.map((p) => (
          <option key={p.patient_id} value={p.patient_id}>
            {p.patient_id} - {p.name}
          </option>
        ))}
      </select>

      {s.alerts.map((a, i) => (
        <div key={i} style={S.alert}>
          🚨 {a}
        </div>
      ))}

      <div style={S.grid}>

        <div style={S.card}>
          <div style={S.label}>Patient</div>
          <div style={{ fontSize: 22, fontWeight: 700 }}>{p.name}</div>
          <div>{p.patient_id}</div>
          <div>{p.age} yrs</div>
          <div>{p.known_condition}</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Heart Rate</div>
          <div style={S.value}>{s.heart_rate.bpm}</div>
          <div>BPM</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Blood Oxygen</div>
          <div style={S.value}>{s.spo2.spo2_pct}%</div>
          <div>SpO2</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Temperature</div>
          <div style={S.value}>{s.temperature.temp_celsius}°C</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Blood Pressure</div>
          <div style={S.value}>
            {s.blood_pressure.systolic}/{s.blood_pressure.diastolic}
          </div>
          <div>mmHg</div>
        </div>

      </div>

      <div style={S.grid}>

        <div style={S.card}>
          <h3>Heart Rate Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.heart_rate}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="bpm" stroke="#2563eb" />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div style={S.card}>
          <h3>SpO2 Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.spo2}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="spo2_pct" stroke="#16a34a" />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div style={S.card}>
          <h3>Temperature Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.temperature}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="temp_celsius" stroke="#dc2626" />
            </LineChart>
          </ResponsiveContainer>
        </div>

      </div>

    </div>
  );
}
